method specialFilter(nums: seq<int>) returns (count: int)
    requires |nums| >= 0
    ensures count >= 0
    ensures count == CountElementsGreaterThanTenWithOddDigits(nums)

    // Helper function to check if a digit is odd
    function IsOdd(d: int): bool
        requires d >= 0 && d <= 9
        ensures result <==> (d == 1 || d == 3 || d == 5 || d == 7 || d == 9)

    // Helper function to check if the first and last digits of a number are odd
    function HasOddFirstAndLastDigits(n: int): bool
        requires n > 0
        ensures result <==> (IsOdd(n % 10) && IsOdd(n / 10 % 10))

    // Helper function to count elements matching the criteria
    function CountElementsGreaterThanTenWithOddDigits(nums: seq<int>): int
        requires |nums| >= 0
        ensures result >= 0
    {
        var count := 0;
        var i: int;
        for i := 0 to |nums| - 1
        {
            if nums[i] > 10 && HasOddFirstAndLastDigits(nums[i]) {
                count := count + 1;
            }
        }
        return count;
    }
